import unittest


def is_palindrome(s):
    return s == s[::-1]


class TestIsPalindrome(unittest.TestCase):
    """Unit tests for the is_palindrome function."""

    def test_empty_string(self):
        """Test that an empty string is considered a palindrome."""
        self.assertTrue(is_palindrome(""))

    def test_single_character(self):
        """Test that a single character string is a palindrome."""
        self.assertTrue(is_palindrome("a"))

    def test_simple_palindrome(self):
        """Test a simple word palindrome."""
        self.assertTrue(is_palindrome("racecar"))

    def test_simple_non_palindrome(self):
        """Test a simple word that is not a palindrome."""
        self.assertFalse(is_palindrome("hello"))

    def test_palindrome_with_spaces(self):
        """Test a palindrome phrase with spaces."""
        self.assertTrue(is_palindrome("a b a"))

    def test_non_palindrome_with_spaces(self):
        """Test a phrase with spaces that is not a palindrome."""
        self.assertFalse(is_palindrome("a b c"))

    def test_palindrome_with_mixed_case(self):
        """Test that case sensitivity is respected (standard behavior)."""
        # "Racecar" is not equal to "racecaR" reversed if case matters
        # s[::-1] on "Racecar" is "racecaR"
        self.assertFalse(is_palindrome("Racecar"))

    def test_palindrome_with_numbers(self):
        """Test a numeric string palindrome."""
        self.assertTrue(is_palindrome("12321"))

    def test_non_palindrome_with_numbers(self):
        """Test a numeric string that is not a palindrome."""
        self.assertFalse(is_palindrome("12345"))

    def test_long_palindrome(self):
        """Test a longer palindrome string."""
        self.assertTrue(is_palindrome("abcdedcba"))

    def test_long_non_palindrome(self):
        """Test a longer non-palindrome string."""
        self.assertFalse(is_palindrome("abcdefghi"))


if __name__ == '__main__':
    unittest.main()
